import { useState } from 'preact/hooks'

export function Counter({ step }: { step: number }) {
  const [count, setCount] = useState(0)
  const doubled = count * 2
  return (
    <button class="counter" onClick={() => setCount(count + step)}>
      {count} / {doubled}
    </button>
